async function checkpoint(f,state,{old=false}={}){const saved=await row(f),detail=await requestDetail(f),customer=f.thread.messages.at(-1),id=hash(JSON.stringify([workspaceTenant(f.client),saved.generation,f.requestId,customer.messageID]));await store.atomicUpdate('lead_connections',f.client.slug+'/'+workspaceTenant(f.client)+'/thumbtack',row=>{const a=structuredClone(row.native.automation),t=a.threads[f.requestId];t.state=state;t.lastCustomerMessageId=customer.messageID;t.turns=[{id,customerMessageId:customer.messageID,sourceRevision:detail.sourceRevision,rulesRevision:setup.configurationRevision(f.client),state:state==='prepared'?'prepared':'generating',startedAt:new Date(Date.now()-(old?120000:0)).toISOString(),...(state==='prepared'?{proposal:proposalInput()}: {})}];return{value:{...row,native:{...row.native,automation:a}}};});}
