await check('Manual owner reply at the 200-thread automation limit cannot corrupt the saved connection',async()=>{const f=await aiFixture();await enable(f);const saved=await row(f),key=f.client.slug+'/'+workspaceTenant(f.client)+'/thumbtack';await store.atomicUpdate('lead_connections',key,row=>{const a=structuredClone(row.native.automation);a.threads={};for(let n=0;n<200;n++)a.threads[hash('capacity-thread-'+n).slice(0,40)]={mode:'automatic',revision:0,state:'idle',reason:null,lastOperationId:null,lastCustomerMessageId:null,lastReplyAt:null,turns:[]};return{value:{...row,native:{...row.native,automation:a}}};});const current=await requestDetail(f),sends=messagePosts(),result=await owner(f,reply(f,saved,current));const retained=await row(f);assert.ok(Object.keys(retained.native.automation.threads).length<=200,'Owner action wrote an invalid201st automation thread');assert.equal((await owner(f)).status,200,'Connection must remain readable at capacity');assert.ok(result.status===200||result.status===409);assert.ok(messagePosts()<=sends+1);});

