async function aimRecoveryAt(f){const slugs=await store.list('clients',''),index=slugs.indexOf(f.client.slug);await store.put('health','thumbtack:recoveryCursor',{slug:slugs[(index+slugs.length-1)%slugs.length],at:new Date().toISOString()});}
await check('Failed initial webhook fetch recovers on the ordinary schedule into Inbox, durable AI turn and keyed background delivery',async()=>{const f=await aiFixture();await enable(f);fault={mode:'before',match:({url,method})=>method==='GET'&&url.pathname==='/api/v4/negotiations/'+f.negotiationID};assert.notEqual((await arrival(f,'Can you repair central AC in Katy?')).status,200);assert.ok((await row(f)).native.pendingNegotiations.includes(f.negotiationID));const before=modelCalls.length,dispatches=backgroundDispatches.length;await aimRecoveryAt(f);assert.equal((await recoveryHandler()).status,200);assert.equal(modelCalls.length,before);assert.equal(backgroundDispatches.length,dispatches+1);assert.equal((await threadState(f)).state,'pending');assert.equal((await row(f)).native.pendingNegotiations.length,0);assert.match(JSON.stringify((await requestDetail(f)).platform.context.messages),/repair central AC/);modelProposal();assert.equal((await run(f)).body.state,'accepted');});
await check('A lost scheduled background dispatch acknowledgment retains the same pending turn and the next wave sends exactly once',async()=>{const f=await aiFixture();await enable(f);fault={mode:'before',match:({url,method})=>method==='GET'&&url.pathname==='/api/v4/negotiations/'+f.negotiationID};await arrival(f);dispatchFault=true;const sends=messagePosts(),before=modelCalls.length,dispatches=backgroundDispatches.length;await aimRecoveryAt(f);await recoveryHandler();assert.equal((await threadState(f)).state,'pending');assert.equal(backgroundDispatches.length,dispatches+1);const first=backgroundDispatches.at(-1);await aimRecoveryAt(f);await recoveryHandler();assert.deepEqual(backgroundDispatches.at(-1),first);assert.equal(modelCalls.length,before);modelProposal();assert.equal((await run(f)).body.state,'accepted');await run(f);assert.equal(messagePosts(),sends+1);assert.equal((await threadState(f)).turns.length,1);});

async function ageCapacityCheckpoint(f){await store.atomicUpdate('lead_connections',f.client.slug+'/'+workspaceTenant(f.client)+'/thumbtack',row=>{const a=structuredClone(row.native.automation),t=a.threads[f.requestId];t.capacityDay='2000-01-01';for(const turn of t.turns)if(turn.state==='waiting_capacity')turn.capacityDay=t.capacityDay;return{value:{...row,native:{...row.native,automation:a}}};});}
async function exhaustBeforeModel(f){await enable(f);await arrival(f);process.env.MC_SELF_SERVICE_AI_GLOBAL_DAILY_LIMIT='0';const result=await run(f);assert.equal(result.body.state,'waiting_capacity');return result;}
await check('Known quota exhaustion before the first model call remains automatic and does not repeat during the same Houston day',async()=>{const f=await aiFixture(),before=modelCalls.length,sends=messagePosts();await exhaustBeforeModel(f);const t=await threadState(f);assert.equal(t.mode,'automatic');assert.equal(t.turns[0].modelAttempts,0);assert.equal(ai.pendingPlatformAIRequest(await row(f)),null);process.env.MC_SELF_SERVICE_AI_GLOBAL_DAILY_LIMIT='50';await run(f);assert.equal(await ai.dispatchPlatformAI(f.client,f.requestId),false);assert.equal(modelCalls.length,before);assert.equal(messagePosts(),sends);assert.equal((await threadState(f)).turns[0].id,t.turns[0].id);});
await check('After the daily reset the ordinary schedule resumes the exact waiting turn without another customer message',async()=>{const f=await aiFixture();await exhaustBeforeModel(f);const turn=(await threadState(f)).turns[0],before=modelCalls.length,sends=messagePosts();await ageCapacityCheckpoint(f);await store.del('self_service_ai','daily');process.env.MC_SELF_SERVICE_AI_GLOBAL_DAILY_LIMIT='50';assert.equal(ai.pendingPlatformAIRequest(await row(f)),f.requestId);const dispatches=backgroundDispatches.length;await aimRecoveryAt(f);await recoveryHandler();assert.equal(backgroundDispatches.length,dispatches+1);modelProposal();assert.equal((await run(f)).body.state,'accepted');assert.equal(modelCalls.length,before+1);assert.equal(messagePosts(),sends+1);const t=await threadState(f);assert.equal(t.turns.length,1);assert.equal(t.turns[0].id,turn.id);assert.equal(t.turns[0].modelAttempts,1);});
await check('Quota exhaustion after one consumed model attempt stays owner review and never becomes an automatic reset retry',async()=>{const f=await aiFixture();await enable(f);await arrival(f);const {houstonToday}=await import('../netlify/functions/lib/availability.mjs');await store.put('self_service_ai','daily',{version:1,day:houstonToday(),used:0,tenants:{},platformPhysical:{used:9,tenants:{[workspaceTenant(f.client)]:9}}});const before=modelCalls.length,sends=messagePosts();modelQueue.push({tools:[{name:'get_availability',input:{date:'2026-10-26',days:1}}]},{text:JSON.stringify(proposalInput())});await run(f);assert.equal(modelCalls.length,before+1);const t=await threadState(f);assert.equal(t.mode,'owner');assert.equal(t.turns[0].modelAttempts,1);assert.notEqual(t.state,'waiting_capacity');await store.del('self_service_ai','daily');await run(f);assert.equal(modelCalls.length,before+1);assert.equal(messagePosts(),sends);});
await check('An owner pause while a known-zero-attempt turn waits for capacity prevents automatic reset delivery',async()=>{const f=await aiFixture();await exhaustBeforeModel(f);assert.equal((await disable(f)).status,200);await ageCapacityCheckpoint(f);await store.del('self_service_ai','daily');process.env.MC_SELF_SERVICE_AI_GLOBAL_DAILY_LIMIT='50';const before=modelCalls.length,sends=messagePosts();await run(f);assert.equal((await automated(f)).mode,'off');assert.equal(modelCalls.length,before);assert.equal(messagePosts(),sends);});

await check('Accepted corrected contact facts drive the retained owner request without granting SMS consent',async()=>{const f=await aiFixture();await enable(f);await arrival(f,'I am Jamie. My old phone was (713) 555-0142 at 12 Oak St. Correction: use (713) 555-0198 and 21 Pine St in Katy instead.');modelProposal({reply:'Your corrected contact details are saved with this request. What is happening with your AC?',summary:'Jamie corrected the phone to (713) 555-0198 and address to 21 Pine St in Katy.',customer_name:'Jamie',phone:'(713) 555-0198',address:'21 Pine St in Katy'});assert.equal((await run(f)).body.state,'accepted');const d=await requestDetail(f);assert.equal(d.source.phone.replace(/\D/g,'').slice(-10),'7135550198','Owner contact must use the customer’s accepted corrected phone');assert.match(d.source.address,/21 Pine St/i);assert.equal(d.state.contact,'not_recorded');assert.notEqual(d.automaticFollowup?.permission?.confirmed,true);for(const kind of ['managed_deliveries','tasks'])assert.equal((await store.list(kind,f.client.slug+'/')).length,0);});

await check('A complete final JSON proposal without a tool call is validated and delivered once',async()=>{const f=await aiFixture();await enable(f);await arrival(f);const before=modelCalls.length,sends=messagePosts();modelQueue.push({text:JSON.stringify(proposalInput())});assert.equal((await run(f)).body.state,'accepted');assert.equal(modelCalls.length,before+1);assert.equal(messagePosts(),sends+1);});
