async function acceptedContact(f,phone,address){await arrival(f,'I am Jamie. Use '+phone+' at '+address+'.');modelProposal({customer_name:'Jamie',phone,address,summary:'Jamie supplied the contact phone and service address.'});assert.equal((await run(f)).body.state,'accepted');return requestDetail(f);}
async function csvExport(f,kind){const response=await handler(new Request(origin+'/api/client?c='+f.client.slug+'&export='+kind,{headers:{Authorization:'Bearer '+f.token,Origin:origin}}));assert.equal(response.status,200);assert.match(response.headers.get('content-type'),/text\/csv/);return response.text();}
await check('Later accepted customer correction supersedes the owner contact in Inbox, native refresh and both exports',async()=>{const f=await aiFixture();await enable(f);const first=await acceptedContact(f,'(713) 555-0142','12 Oak St in Katy');const firstFact=first.customerFacts.fields.phone;assert.ok(firstFact.turnId&&firstFact.providerMessageId);const second=await acceptedContact(f,'(713) 555-0198','21 Pine St in Katy');assert.equal(second.source.phone,'+17135550198');assert.equal(second.source.address,'21 Pine St in Katy');assert.notEqual(second.customerFacts.fields.phone.turnId,firstFact.turnId);assert.equal(second.customerFacts.fields.phone.raw,'(713) 555-0198');await incoming(f);assert.equal((await requestDetail(f)).source.phone,'+17135550198');assert.equal((await requestDetail(f)).source.address,'21 Pine St in Katy');for(const kind of ['leads','customers']){const csv=await csvExport(f,kind);assert.match(csv,/\+17135550198/);assert.match(csv,/21 Pine St/);assert.doesNotMatch(csv,/\+17135550142/);}const stale=await owner(f,{action:'request_followthrough',requestId:f.requestId,sourceRevision:first.sourceRevision,expectedRevision:first.revision,operationId:operationID(),type:'attempt',channel:'call',result:'no_answer',note:'Obsolete phone attempt'});assert.equal(stale.status,409);assert.equal((await requestDetail(f)).state.contact,'not_recorded');for(const kind of ['managed_sms_consent','request_followup_permissions','managed_deliveries'])assert.equal((await store.list(kind,f.client.slug+'/')).length,0);});
async function failProjectionOnce(f){const original=Map.prototype.set,target=f.client.slug+'/'+f.requestId;let injected=false;Map.prototype.set=function(key,value){if(!injected&&key===target&&typeof value?.value==='string'&&JSON.parse(value.value).platformQualification){injected=true;throw Error('Synthetic durable contact projection write failed');}return original.call(this,key,value);};try{await run(f);}finally{Map.prototype.set=original;}assert.equal(injected,true);}
